import bisect

def length_of_lis(nums):
    """Find length of longest increasing subsequence using patience sorting and binary search in O(N log N)."""
    tails = []
    for x in nums:
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

